<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { getDictItems, updateDictItem, type DictItem } from '@/api/admin'; import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore();const type=ref('DANCE_TYPE');const records=ref<DictItem[]>([]);const loading=ref(false);const editing=ref<DictItem>();const dialog=ref(false);const form=ref({dictLabel:'',dictValue:'',sortNo:0,status:1})
async function load(){loading.value=true;try{records.value=(await getDictItems(type.value)).data}finally{loading.value=false}}function edit(item:DictItem){editing.value=item;form.value={dictLabel:item.dictLabel,dictValue:item.dictValue,sortNo:item.sortNo,status:item.status};dialog.value=true}async function save(){if(!editing.value)return;await updateDictItem(editing.value.id,form.value);dialog.value=false;ElMessage.success('字典项已保存');await load()}onMounted(load)
</script>
<template><section class="content"><div class="title"><div><h1>系统设置</h1><p>维护平台舞种和课程难度字典。</p></div></div><el-tabs v-model="type" @tab-change="load"><el-tab-pane label="舞种" name="DANCE_TYPE"/><el-tab-pane label="课程难度" name="COURSE_DIFFICULTY"/></el-tabs><el-table v-loading="loading" :data="records" stripe><el-table-column prop="dictLabel" label="显示名称"/><el-table-column prop="dictValue" label="字典值"/><el-table-column prop="sortNo" label="排序" width="100"/><el-table-column label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.status?'success':'info'">{{scope.row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="auth.isSuperAdmin" link type="primary" @click="edit(scope.row)">编辑</el-button><span v-else>只读</span></template></el-table-column></el-table><el-dialog v-model="dialog" title="编辑字典项" width="460px"><el-form label-position="top"><el-form-item label="显示名称"><el-input v-model="form.dictLabel"/></el-form-item><el-form-item label="字典值"><el-input v-model="form.dictValue"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.content{padding:0}.title{margin-bottom:18px}.title h1{margin:0;color:var(--df-primary-950)}.title p{margin:8px 0 0;color:#77717e}</style>
